use std::collections::HashSet;

impl Solution {
    pub fn number_of_special_chars(word: String) -> i32 {
        let mut count = 0;
        let mut set = HashSet::new();
        let chars: Vec<char> = word.chars().collect();

        for i in 0..chars.len() {
            if chars[i].is_lowercase() {
                let lower = chars[i].to_lowercase().next().unwrap();
                let upper = chars[i].to_uppercase().next().unwrap();

                if !set.contains(&lower) && !set.contains(&upper) {
                    let remaining_chars: String = chars[i+1..].iter().collect();
                    let preceding_chars: String = chars[..i].iter().collect();

                    if !remaining_chars.contains(lower) && 
                       remaining_chars.contains(upper) && 
                       !preceding_chars.contains(upper) {
                        set.insert(lower);
                        set.insert(upper);
                        count += 1;
                    }
                }
            }
        }
        count
    }
}
